{
  "title": "A slower day in Đà Lạt",
  "summary": "One gentle market wander, then a long lunch and a long dinner with plenty of room to breathe.",
  "stops": [
    {
      "poi_id": "p40",
      "kind": "activity",
      "must_do_id": null,
      "note": "From what Tokek knows so far, the market is the one activity that fits a slower day and it is uncurated, so treat the hours as a guess."
    },
    {
      "poi_id": "p22",
      "kind": "meal",
      "must_do_id": "m2",
      "note": "From what Tokek knows so far, this is the kept lunch and it stays right where it belongs."
    },
    {
      "poi_id": "p123",
      "kind": "meal",
      "must_do_id": null,
      "note": "From what Tokek knows so far, dinner moves here so the evening stays in the same part of the map as the market."
    }
  ]
}
